import{_ as a,o as i,c as e,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const k=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/reference/troubleshooting.md","filePath":"ja/reference/troubleshooting.md"}'),l={name:"ja/reference/troubleshooting.md"};function o(n,s,r,p,h,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><h2 id="gatekeeperがアプリをブロックする" tabindex="-1">Gatekeeperがアプリをブロックする <a class="header-anchor" href="#gatekeeperがアプリをブロックする" aria-label="Permalink to &quot;Gatekeeperがアプリをブロックする&quot;">​</a></h2><p>OrchestraはApple Developer証明書で署名されていないため、macOS Gatekeeperがブロックする場合があります。</p><p><strong>解決策:</strong> インストール後に以下のコマンドを実行してください:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Orchestra.app</span></span></code></pre></div><h2 id="hookイベントが表示されない" tabindex="-1">Hookイベントが表示されない <a class="header-anchor" href="#hookイベントが表示されない" aria-label="Permalink to &quot;Hookイベントが表示されない&quot;">​</a></h2><p>セッションがOrchestraのダッシュボードに表示されない場合。</p><p><strong>Hook設定を確認:</strong></p><ol><li><code>~/.claude/settings.json</code>を開く</li><li><code>hooks</code>セクションに必要な全イベント（PreToolUse, PostToolUse, Stop, Notification, SubagentStop, SessionEnd）が含まれているか確認</li><li>curlコマンドが<code>http://localhost:3008/api/ingest/hook</code>を指していることを確認</li></ol><p><strong>Orchestraが実行中か確認:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ポート3008がリッスンしているか確認</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3008</span></span></code></pre></div><p>何もリッスンしていない場合、Orchestraが起動されていることを確認してください。</p><h2 id="ポート3008が使用中" tabindex="-1">ポート3008が使用中 <a class="header-anchor" href="#ポート3008が使用中" aria-label="Permalink to &quot;ポート3008が使用中&quot;">​</a></h2><p>別のアプリケーションがポート3008を使用しており、Orchestraが起動できない場合。</p><p><strong>解決策:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ポート3008を使用しているプロセスを確認</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3008</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必要に応じてプロセスをkill</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>その後、Orchestraを再起動してください。</p><h2 id="セッションが更新されない" tabindex="-1">セッションが更新されない <a class="header-anchor" href="#セッションが更新されない" aria-label="Permalink to &quot;セッションが更新されない&quot;">​</a></h2><p>セッションは表示されるがリアルタイムで更新されない場合。</p><p><strong>考えられる原因:</strong></p><ol><li><strong>Claude Codeが再起動された</strong> — Orchestraを再起動して接続をリフレッシュ</li><li><strong>Hook設定が変更された</strong> — <code>~/.claude/settings.json</code>のhooksを確認</li><li><strong>ネットワークの問題</strong> — <code>localhost:3008</code>にアクセス可能か確認</li></ol><h2 id="アプリが起動時にクラッシュする" tabindex="-1">アプリが起動時にクラッシュする <a class="header-anchor" href="#アプリが起動時にクラッシュする" aria-label="Permalink to &quot;アプリが起動時にクラッシュする&quot;">​</a></h2><p><strong>ログを確認:</strong></p><ol><li><code>Console.app</code>を開く</li><li>&quot;Orchestra&quot;でフィルタ</li><li>クラッシュレポートやエラーメッセージを確認</li></ol><p><strong>一般的な解決策:</strong></p><ul><li>アプリを削除し、新しいDMGから再インストール</li><li>macOSが11.0以上に更新されていることを確認</li><li>ポート3008で競合するアプリケーションがないか確認</li></ul><h2 id="jumpボタンが動作しない" tabindex="-1">Jumpボタンが動作しない <a class="header-anchor" href="#jumpボタンが動作しない" aria-label="Permalink to &quot;Jumpボタンが動作しない&quot;">​</a></h2><p>Jumpボタンは表示されるがクリックしてもセッションに切り替わらない場合。</p><p><strong>考えられる原因:</strong></p><ol><li><strong>tmuxがインストールされていない</strong> — <code>brew install tmux</code>でインストール</li><li><strong>セッションがtmux内にない</strong> — Claude Codeセッションはtmuxセッション内で実行する必要があります</li><li><strong>iTerm2が実行されていない</strong> — フルフォーカスサポートにはiTerm2を使用してください</li></ol>`,30)])])}const g=a(l,[["render",o]]);export{k as __pageData,g as default};
